"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type BlurPrimitiveProps = ComponentProps<typeof motion.div>;

export function BlurPrimitive({ children, ...props }: BlurPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {opacity: 0,filter: "blur(14px)"}}
      animate={{opacity: 1,filter: "blur(0px)"}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.26, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
